using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
namespace HarborValeGreybox.Racing.Editor {
public static class TempestImport {
 public static void Prepare(){string asset="Assets/HarborValeGreybox/Lineup/Art/Tempest_R.fbx";AssetDatabase.ImportAsset(asset,ImportAssetOptions.ForceSynchronousImport);var importer=AssetImporter.GetAtPath(asset)as ModelImporter;importer.importCameras=false;importer.importLights=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.SaveAndReimport();var source=AssetDatabase.LoadAssetAtPath<GameObject>(asset);var root=new GameObject("Aster Tempest R | Blender original visual");var visual=(GameObject)PrefabUtility.InstantiatePrefab(source);PrefabUtility.UnpackPrefabInstance(visual,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);visual.transform.SetParent(root.transform,false);string[] names={"Front left wheel pivot","Front right wheel pivot","Rear left wheel pivot","Rear right wheel pivot"};var pivots=names.Select(n=>visual.GetComponentsInChildren<Transform>().Single(t=>t.name==n)).ToArray();var forward=(pivots[0].position+pivots[1].position-pivots[2].position-pivots[3].position).normalized;var right=(pivots[1].position+pivots[3].position-pivots[0].position-pivots[2].position).normalized;var rotate=Quaternion.Inverse(Quaternion.LookRotation(forward,Vector3.Cross(forward,right)));visual.transform.rotation=rotate*visual.transform.rotation;Vector3 center=pivots.Aggregate(Vector3.zero,(a,t)=>a+t.position)/4;visual.transform.position-=center-new Vector3(0,.465f,0);foreach(var p in pivots){p.SetParent(root.transform,true);var wheel=p.GetComponentsInChildren<MeshRenderer>().FirstOrDefault(r=>r.name.StartsWith("Wheel"));if(wheel!=null){float offset=p.position.y-wheel.bounds.center.y;foreach(Transform child in p)child.position+=Vector3.up*offset;}}foreach(var p in pivots)foreach(var caliper in p.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Caliper_")).ToArray())caliper.SetParent(visual.transform,true);foreach(var c in root.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);var box=new System.Collections.Generic.List<string>();foreach(var p in pivots)box.Add(p.name+" "+p.localPosition.ToString("F3"));PrefabUtility.SaveAsPrefabAsset(root,"Assets/HarborValeGreybox/Lineup/Resources/car_tempest.prefab");System.IO.Directory.CreateDirectory("Verification/Lineup");System.IO.File.WriteAllLines("Verification/Lineup/tempest-pivots.txt",box);UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();}
}
}
